import {useEffect,useState} from 'react';
import {api} from './api';
import {Addresses,Blank,Feedback,Section} from './common';
import {platform,timestamp,useResource} from './data';
export function ReportedMap({point,stale=false,simulated=false}){const [enabled,setEnabled]=useState(false);if(!point)return <Blank title="Waiting for the rider’s first location.">The map appears when the assigned rider shares a position.</Blank>;const coordinates=`${point.latitude},${point.longitude}`;return <div className="delivery-map">{enabled?<iframe title="Reported package location on Google Maps" src={`https://maps.google.com/maps?q=${encodeURIComponent(coordinates)}&z=15&output=embed`} loading="lazy" referrerPolicy="no-referrer"/>:<div className="map-consent"><h3>See the reported location</h3><p>Loading the map shares this delivery position and your connection with Google Maps.</p><button className="primary" onClick={()=>setEnabled(true)}>Load Google map</button></div>}<p className="small">{simulated?'Simulated position':stale?'Out-of-date position':'GPS position'} · Last received {timestamp(point.recordedAt)} · Accuracy {Math.round(point.accuracyMeters)} m</p><a className="text-button" href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(coordinates)}`} target="_blank" rel="noreferrer">Open in Google Maps ↗</a></div>;}
function PackageMap({id}){const r=useResource(()=>api(`/services/orders/${id}/tracking`),[id]);useEffect(()=>{const timer=setInterval(()=>{if(!document.hidden)void r.refresh();},15000);return()=>clearInterval(timer);},[r.refresh]);return <><Feedback resource={r}/>{r.data&&!r.error?<><p className="small" role="status">Location status: <strong>{r.data.state==='reported'?'GPS received':r.data.state==='stale'?'Last location is out of date':r.data.state==='simulated'?'Simulated location':'Waiting for rider GPS'}</strong></p><ReportedMap point={r.data.point} stale={r.data.state==='stale'} simulated={r.data.state==='simulated'}/><p className="small muted">Refreshes every 15 seconds. The assigned rider can share GPS while DEN is open. Traffic and arrival estimates are not connected.</p></>:null}</>;}
export default function DeliveryMap({user}){const r=useResource(()=>platform('/orders')),[selected,setSelected]=useState(''),[addresses,setAddresses]=useState(false);useEffect(()=>{const timer=setInterval(()=>{if(!document.hidden)void r.refresh();},15000);return()=>clearInterval(timer);},[r.refresh]);const orders=r.data?.orders.filter(o=>o.consumer_id===user.id&&o.state!=='delivered')??[];const active=orders.find(o=>o.id===selected)??orders[0];return <><div className="page-heading"><div><h1>Follow your delivery.</h1><p>Your packages and their latest reported location.</p></div><button className="secondary" onClick={()=>setAddresses(!addresses)}>{addresses?'Hide destinations':'Saved destinations'}</button></div><Feedback resource={r}/>{orders.length?<Section title="Active deliveries"><label className="field"><span>Package</span><select value={active.id} onChange={e=>setSelected(e.target.value)}>{orders.map(o=><option key={o.id} value={o.id}>{o.organization_name} · {o.id.slice(0,8)}</option>)}</select></label>{active.rider_id?<PackageMap key={active.id} id={active.id}/>:<Blank title="Waiting for a rider.">Tracking starts once a rider is assigned and shares a location.</Blank>}</Section>:r.data?<Blank title="No active deliveries.">Your package map will appear here after you place an order.</Blank>:null}{addresses?<Addresses/>:null}</>;}
